import{_ as e,o,c as s,ah as n}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Staff and user accounts","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/personnel-utilisateurs.md","filePath":"src/en/guide/admin/personnel-utilisateurs.md"}'),a={name:"en/guide/admin/personnel-utilisateurs.md"};function r(i,t,l,c,d,h){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="staff-and-user-accounts" tabindex="-1">Staff and user accounts <a class="header-anchor" href="#staff-and-user-accounts" aria-label="Permalink to &quot;Staff and user accounts&quot;">​</a></h1><p>This section covers two distinct things that shouldn&#39;t be confused: the <strong>user account</strong> (sign-in credentials + role, under <strong>Users</strong>) and the <strong>employee record</strong> (position, site, contracts, in the <strong>Staff</strong> group). A teacher, for example, needs both — an account to sign in, a record for their position and contracts — but these are two separate screens.</p><h2 id="create-a-user-account-and-assign-a-role" tabindex="-1">Create a user account and assign a role <a class="header-anchor" href="#create-a-user-account-and-assign-a-role" aria-label="Permalink to &quot;Create a user account and assign a role&quot;">​</a></h2><p><strong>Users</strong> (in the menu&#39;s <strong>Administration</strong> group) lists every account in the school, with a search by name/email, a filter by role, and each account&#39;s <strong>Sign-in</strong> (Invitation sent, Invitation expired or Activated) and active/inactive status.</p><p>To create a user:</p><ol><li>Click <strong>New user</strong>.</li><li>Fill in the <strong>Name</strong> and <strong>Email address</strong>. There&#39;s no password to enter: the person chooses their own.</li><li>Choose the <strong>Role</strong>: User, Admin, Teacher, Secretariat, Cashier, School life, Boarding manager, Nurse, or Document manager — and, if the school has the Pilotage module, <strong>Site director</strong> or <strong>General director</strong>.</li><li>For a <strong>Site director</strong>, tick the <strong>Sites run</strong> (at least one).</li><li>Click <strong>Create the user</strong>.</li></ol><p>The person immediately gets an invitation e-mail with an <strong>Activate my account</strong> button. The link, valid for <strong>7 days</strong>, takes them to a page where they choose their password; they are then signed straight in. You never know their password, and have nothing to hand over.</p><h3 id="following-up-an-invitation" tabindex="-1">Following up an invitation <a class="header-anchor" href="#following-up-an-invitation" aria-label="Permalink to &quot;Following up an invitation&quot;">​</a></h3><p>The list&#39;s <strong>Sign-in</strong> column shows where each account stands:</p><table tabindex="0"><thead><tr><th>Sign-in</th><th>Meaning</th></tr></thead><tbody><tr><td>Invitation sent</td><td>the link went out and is still valid (its deadline is on the account)</td></tr><tr><td>Invitation expired</td><td>7 days passed without activation: resend the invitation</td></tr><tr><td>Activated</td><td>the person chose their password</td></tr></tbody></table><p>On an account not yet activated (<strong>Edit</strong>), the <strong>Sign-in</strong> section offers:</p><ul><li><strong>Resend invitation</strong> — sends a new e-mail, with a new link valid for 7 days. The old link stops working.</li><li><strong>Copy invitation link</strong> — for someone who doesn&#39;t get the e-mail (full mailbox, message in spam): a new link is shown and copied, for you to hand over yourself (WhatsApp, text message…). It replaces the e-mailed link, which stops working. Only give it to the person concerned: it opens the account.</li></ul><p>If you correct the <strong>Email address</strong> of an account not yet activated, a new invitation goes out to the right address automatically.</p><div class="tip custom-block"><p class="custom-block-title">Forgotten password</p><p>For an account already activated, the <strong>Sign-in</strong> section offers <strong>Send a password reset link</strong>: the person gets the usual &quot;forgot password&quot; e-mail and chooses a new password themselves. They can also ask for it on their own, from the sign-in screen.</p></div><div class="tip custom-block"><p class="custom-block-title">The direction profiles</p><p>They go to the people who run the school without doing its data entry: campus heads, the head of school. They see the requests to approve for their sites, not the operational screens. An account has a single role: if the head of school also administers the application, keep them Admin, which can already approve everything. See <a href="/era-guide/en/guide/direction/">Direction</a>.</p></div><p>From the list, each account offers:</p><ul><li><strong>Edit</strong> — change the name, email or role, and manage sign-in (see above). Changing the role of a staff member who is also a parent keeps their parent access: only the work role is replaced.</li><li><strong>Activate</strong> / <strong>Deactivate</strong> — deactivating an account signs it out everywhere immediately and blocks any new sign-in, without deleting the account; reactivating restores access.</li><li><strong>Delete</strong> — permanent and irreversible.</li><li><strong>Export CSV</strong> (top of the page) — exports the currently filtered list.</li></ul><h2 id="manage-staff-records-and-contracts" tabindex="-1">Manage staff records and contracts <a class="header-anchor" href="#manage-staff-records-and-contracts" aria-label="Permalink to &quot;Manage staff records and contracts&quot;">​</a></h2><p>The <strong>Employees</strong> page (in the <strong>Staff</strong> group) lists employee records — position, site, hire date, and status — distinct from user accounts.</p><p>To create an employee record:</p><ol><li>Click <strong>New employee</strong>.</li><li>Fill in the &quot;Person&quot; section fields below.</li><li>Fill in the &quot;Assignment&quot; section fields below.</li><li>Click <strong>Save</strong>.</li></ol><p>&quot;Person&quot; section:</p><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Staff account</td><td>chosen from staff accounts, direction included, that have no record yet</td></tr><tr><td>Position</td><td>free text</td></tr></tbody></table><p>&quot;Assignment&quot; section:</p><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Site</td><td>leave &quot;Unassigned&quot; if needed</td></tr><tr><td>Hire date</td><td>—</td></tr><tr><td>Status</td><td>Active or Inactive</td></tr></tbody></table><p>Deleting an employee record also permanently deletes its contracts.</p><h3 id="contracts" tabindex="-1">Contracts <a class="header-anchor" href="#contracts" aria-label="Permalink to &quot;Contracts&quot;">​</a></h3><p>From an employee&#39;s record (<strong>Edit</strong> in the list), the <strong>Contracts</strong> section lists their contracts and lets you add one:</p><ol><li>Click <strong>New contract</strong>.</li><li>Fill in the <strong>Type</strong> (Permanent, Fixed-term, or Internship), the <strong>Start date</strong>, the <strong>End date</strong> (optional), a <strong>Document</strong> to upload (PDF, JPG, or PNG), and free-text <strong>Notes</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>Each listed contract then offers <strong>View document</strong> (if there is one) and <strong>Delete</strong> (permanent, also deletes the document).</p><h2 id="assign-teachers-to-classes-and-subjects" tabindex="-1">Assign teachers to classes and subjects <a class="header-anchor" href="#assign-teachers-to-classes-and-subjects" aria-label="Permalink to &quot;Assign teachers to classes and subjects&quot;">​</a></h2><p><strong>School setup → Teacher Assignments</strong> is what authorizes a teacher to enter grades or observations for a given class — without an assignment, they have access to nothing.</p><p>To create an assignment:</p><ol><li>Click <strong>New assignment</strong>.</li><li>Choose the <strong>Teacher</strong>, then the <strong>Class</strong>.</li><li>If the class belongs to a qualitative department (nursery/preschool, competency-based grading), the <strong>Subject</strong> field disappears — the teacher is assigned to the whole class. Otherwise, choose the <strong>Subject</strong> taught.</li><li>Click <strong>Save</strong>.</li></ol><p>Deleting an assignment immediately removes the teacher&#39;s access to the corresponding grade entry.</p><h2 id="handle-a-staff-transfer-between-sites" tabindex="-1">Handle a staff transfer between sites <a class="header-anchor" href="#handle-a-staff-transfer-between-sites" aria-label="Permalink to &quot;Handle a staff transfer between sites&quot;">​</a></h2><p>A staff transfer moves an employee from one site to another, once the request is approved.</p><p><strong>Requesting a transfer</strong> (from the employee&#39;s record, &quot;Site transfer&quot; section):</p><ol><li>Click <strong>Request transfer</strong>.</li><li>Choose the <strong>Destination site</strong> and give a <strong>Reason</strong>.</li><li>Click <strong>Submit request</strong>.</li></ol><p>The other administrators, the general direction and the direction of both sites are then notified. Any of them may decide; the first decision closes the request. Nothing prevents the administrator who submitted the request from approving it themselves.</p><p><strong>Reviewing a request</strong> — the <strong>Staff → Staff transfers</strong> section lists requests, with a filter by status (Pending, Approved, Rejected). Open a request via <strong>Review</strong> to see the employee, the origin and destination sites, the reason, then:</p><ul><li><strong>Approve</strong> — applies the transfer.</li><li><strong>Reject</strong> — opens a dialog asking for a mandatory rejection reason.</li></ul><p>A request can also be handled from the notification received, which opens the <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a> page with the same <strong>Approve</strong> / <strong>Reject</strong> actions.</p>',43)])])}const u=e(a,[["render",r]]);export{p as __pageData,u as default};
